('devpost:ai-for-good-sprint','AI for Good weekend sprint','AI for Good Lab','Devpost','hackathon',((date_trunc('day', (now() at time zone 'utc')) + interval '30 days' + interval '9 hours') at time zone 'utc'),((date_trunc('day', (now() at time zone 'utc')) + interval '30 days' + interval '9 hours') at time zone 'utc') + interval '36 hours','virtual',null,null,null,null,'free','Free',ARRAY['Python','Machine Learning','Cloud']::text[],'https://devpost.com/hackathons','Remote teams, NGO briefs, and mentors on call. First-time hackers get paired deliberately, not left to fend.',16),
('wit:mums-in-tech-returners','Returners circle: back into tech after a break','Mums in Tech CH','Women in Tech Community Calendar','women_program',((date_trunc('day', (now() at time zone 'utc')) + interval '12 days' + interval '10 hours') at time zone 'utc'),((date_trunc('day', (now() at time zone 'utc')) + interval '12 days' + interval '10 hours') at time zone 'utc') + interval '2 hours','hybrid','Zurich','CH',47.3769,8.5417,'free','Free',ARRAY['Career change','Networking','Interviewing']::text[],'https://www.womenwhocode.com/','A gentle, practical circle on returning after time out: how to frame the gap, and who is genuinely welcoming.',9),
('meetup:sql-clinic-online','SQL clinic: window functions without fear','SQL Study Group','Meetup','workshop',((date_trunc('day', (now() at time zone 'utc')) + interval '1 days' + interval '18 hours') at time zone 'utc'),((date_trunc('day', (now() at time zone 'utc')) + interval '1 days' + interval '18 hours') at time zone 'utc') + interval '2 hours','virtual',null,null,null,null,'free','Free',ARRAY['SQL','Data Visualisation']::text[],'https://www.meetup.com/','One query, built up line by line, until window functions stop looking like hieroglyphs.',8),
('linkedin:public-speaking-tech','Speaking up: your first tech talk','Speak Easy Tech','LinkedIn Events','women_program',((date_trunc('day', (now() at time zone 'utc')) + interval '23 days' + interval '17 hours') at time zone 'utc'),((date_trunc('day', (now() at time zone 'utc')) + interval '23 days' + interval '17 hours') at time zone 'utc') + interval '2 hours','virtual',null,null,null,null,'free','Free',ARRAY['Communication','Networking','Portfolio']::text[],'https://www.linkedin.com/events/','Draft a five-minute talk from something you already built, and practise it once in a room that is on your side.',11),
('eventbrite:zurich-tech-careers-fair','Zurich Tech Careers Fair','Swiss Tech Careers','Eventbrite','conference',((date_trunc('day', (now() at time zone 'utc')) + interval '36 days' + interval '10 hours') at time zone 'utc'),((date_trunc('day', (now() at time zone 'utc')) + interval '36 days' + interval '10 hours') at time zone 'utc') + interval '7 hours','in_person','Zurich','CH',47.3769,8.5417,'free','Free with registration',ARRAY['Interviewing','Networking','React','SQL']::text[],'https://www.eventbrite.com/','Forty teams hiring in Switzerland, plus a quiet room and a CV desk if the hall gets loud.',20),
